import{z as s,x as l,o as B,c as D,q as A,j as n,D as a,d as e,s as i,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"破产与重整","description":"","frontmatter":{"title":"破产与重整","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cf-bankruptcy-restructuring.md","filePath":"econ/cf-bankruptcy-restructuring.md","lastUpdated":1791063341000}'),c={name:"econ/cf-bankruptcy-restructuring.md"};function p(d,E,h,C,u,f){const t=l("Mermaid");return B(),D("div",null,[E[2]||(E[2]=A('<h1 id="破产与重整" tabindex="-1">破产与重整 <a class="header-anchor" href="#破产与重整" aria-label="Permalink to &quot;破产与重整&quot;">​</a></h1><div class="epigraph"><p>破产法不是给失败者的慈善，而是写给所有借款人的保险条款：重整程序怎么写，事前的资本结构就怎么长。</p><footer>—— 据 White 1989 与 Djankov 等 2008 整理</footer></div><p><a href="/econ/cf-esg-corporate">上一课</a>把目标函数的扩展钉住：长期目标与利益相关者偏好。目标失败、现金流断裂时的制度如何接盘，是公司金融的收尾问题。主干已铺了三块基础：<a href="/econ/tradeoff-capital">权衡理论与破产成本</a>把破产成本钉为资本结构的权衡项，<a href="/econ/debt-overhang">债务积压</a>钉了困境下的激励扭曲，<a href="/econ/chapter-11">第 11 章破产</a>介绍了美国程序的基本构件。本课把它们接成一条机制链：程序为什么这样设计、控制权怎么移转、成本真实落在哪里。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>困境企业两条出路——清算与重整——对应不同的损失结构。清算把资产交给次优用途，损失集中在专用性资产；重整保住持续经营价值，但要先解三个谈判问题：信息不对称（资产真实价值只有内部人知道）、融资真空（没人愿给困境企业新钱）、控制权悬置（债与股的优先权地图和真实谈判力错位）。程序设计的全部内容，就是回应这三点。分工由此而定：治理管失败之前的激励，破产管失败之后的谈判。</p><p><span class="marginnote">清算与重整可以翻译成「拆卖」与「整修后继续开」：清算把餐厅的灶台、桌椅分头卖掉，各得残值；重整保留这家店的位置、招牌和老客。只要继续经营的价值高于拆卖残值就选重整——资产越专用（客源、配方、执照），拆卖折价越狠，这条界线画得越清楚。</span></p><h3 id="三个构件" tabindex="-1">三个构件 <a class="header-anchor" href="#三个构件" aria-label="Permalink to &quot;三个构件&quot;">​</a></h3><p>以 Chapter 11 为解剖样本，三个构件各有靶子。自动中止（automatic stay）冻结个别追偿，保住持续经营价值不因债权人抢夺而耗散——针对谈判的外部性。专属申请期（exclusivity）让管理层在一段窗口内垄断提出方案的权力——用时间换谈判秩序，代价是容忍在位者留任。DIP 融资（debtor-in-possession）给新钱优先地位——针对融资真空。绝对优先规则（APR）规定清偿顺序，实证上大量案件偏离：重整本质是谈判，规则只是谈判的起点而非终点。</p><p><span class="marginnote">直觉类比：DIP 融资像给被困荒岛的球队空投补给，并且规定这批补给第一个领。「优先受偿」让新钱不怕被旧债赖账，本已无人敢碰的困境企业重新有人愿意放款——它治的正是「没人愿给困境企业新钱」的融资真空。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成本核算要分两层。直接成本（法律、行政费用）按 Altman 1984 的量级只占资产价值的百分之几；间接成本（销售流失、供应商收紧信用、员工离职）更大且更难度量——而最贵的是激励成本：债务积压使股东拒绝正 NPV 项目，价值在进法庭之前就流走了。所以「破产成本有多大」的正确读法是：程序费是小头，事前扭曲是大头，权衡理论里的那个「破产成本」多数时候指的是后者。跨国比较用 Djankov 等 2008 的程序度量：回收率、时间与成本的差异系统性地解释了各国信贷可得性的差异——程序设计通过资本结构起作用，而不只在坏日子起作用。</p><p><span class="marginnote">常见误区：以为「破产成本」就是律师费。法庭费用通常只占资产价值的百分之几；大头发生在进法庭之前——债务积压让股东放着正 NPV 的项目不做，供应商收紧账期、关键员工出走。读权衡理论时，「破产成本」多数指这些事前扭曲，不是程序账单。</span></p>',12)),(B(),n(o,null,{default:a(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIST%5B%22%E7%8E%B0%E9%87%91%E6%B5%81%E6%96%AD%E8%A3%82%22%5D%20--%3E%20CHOICE%7B%22%E6%B8%85%E7%AE%97%E8%BF%98%E6%98%AF%E9%87%8D%E6%95%B4%3F%22%7D%0A%20%20CHOICE%20--%3E%7C%E8%B5%84%E4%BA%A7%E4%B8%93%E7%94%A8%E6%80%A7%E4%BD%8E%7C%20LIQ%5B%22%E6%B8%85%E7%AE%97%EF%BC%9A%E6%AC%A1%E4%BC%98%E7%94%A8%E9%80%94%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20CHOICE%20--%3E%7C%E6%8C%81%E7%BB%AD%E7%BB%8F%E8%90%A5%E4%BB%B7%E5%80%BC%E9%AB%98%7C%20REO%5B%22%E9%87%8D%E6%95%B4%EF%BC%9A%E8%BF%9B%E5%85%A5%E7%A8%8B%E5%BA%8F%22%5D%0A%20%20REO%20--%3E%20STAY%5B%22%E8%87%AA%E5%8A%A8%E4%B8%AD%E6%AD%A2%22%5D%20--%3E%20EXCL%5B%22%E4%B8%93%E5%B1%9E%E7%94%B3%E8%AF%B7%E6%9C%9F%22%5D%0A%20%20DIP%5B%22DIP%20%E8%9E%8D%E8%B5%84%22%5D%20--%3E%20NEG%5B%22%E8%B0%88%E5%88%A4%E4%B8%8E%20APR%20%E5%81%8F%E7%A6%BB%22%5D%0A%20%20EXCL%20--%3E%20NEG%0A%20%20NEG%20--%3E%20OUT%5B%22%E5%87%BA%E6%B8%85%EF%BC%9A%E6%8E%A7%E5%88%B6%E6%9D%83%E4%B8%8E%E6%B8%85%E5%81%BF%E5%9C%B0%E5%9B%BE%E9%87%8D%E7%94%BB%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=r("p",null,"为什么重整需要专属期：信息不对称下即时出售必然按次优用途贱卖，专属期用在位者的提案权换时间；代价是低效管理者可能多留任一程——程序在「卖便宜」与「人留错」之间定价。为什么 APR 会偏离：偏离是支付给「合作」的价款——债权人接受低于面值换速度，股东拿到超出剩余的份额作为不闹事的补偿；规则被再谈判，正说明它是谈判的均衡起点。为什么程序选择本身是信号与事前约束：债务人友好的程序降低事前承诺的可信度，事前债务成本更高、条款更依赖抵押——法律通过事前价格塑造资本结构，本课的结论与第一课的约束度量在这一点上闭合。",-1)),(B(),n(o,null,{default:a(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20V%5B%22%E9%87%8D%E6%95%B4%E4%BB%B7%E5%80%BC%EF%BC%9A%E4%B8%80%E5%9D%97%E5%BE%85%E5%88%86%E7%9A%84%E8%9B%8B%E7%B3%95%22%5D%20--%3E%20APR%5B%22%E7%BB%9D%E5%AF%B9%E4%BC%98%E5%85%88%E8%A7%84%E5%88%99%EF%BC%9A%E6%8C%89%E9%A1%BA%E5%BA%8F%E5%88%87%22%5D%0A%20%20APR%20--%3E%20S%5B%22%E5%80%BA%E6%9D%83%E4%BA%BA%E6%8C%89%E9%9D%A2%E5%80%BC%E4%BC%98%E5%85%88%E5%8F%97%E5%81%BF%22%5D%0A%20%20N%5B%22%E8%B0%88%E5%88%A4%E7%8E%B0%E5%AE%9E%EF%BC%9A%E6%8B%96%E4%B8%8B%E5%8E%BB%E5%A4%A7%E5%AE%B6%E9%83%BD%E4%BA%8F%22%5D%20--%3E%20C%5B%22%E5%80%BA%E6%9D%83%E4%BA%BA%E8%AE%A9%E5%88%A9%E6%8D%A2%E9%80%9F%E5%BA%A6%22%5D%0A%20%20N%20--%3E%20E%5B%22%E8%82%A1%E4%B8%9C%E5%88%86%E5%88%B0%E8%B6%85%E5%87%BA%E5%89%A9%E4%BD%99%E7%9A%84%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20C%20--%3E%20DEV%5B%22%E6%B8%85%E5%81%BF%E5%9C%B0%E5%9B%BE%E5%81%8F%E7%A6%BB%20APR%22%5D%0A%20%20E%20--%3E%20DEV%0A%20%20DEV%20--%3E%20P%5B%22%E5%81%8F%E7%A6%BB%E9%A2%9D%20%3D%20%E8%B4%AD%E4%B9%B0%E3%80%8C%E5%90%88%E4%BD%9C%E3%80%8D%E7%9A%84%E4%BB%B7%E6%A0%BC%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p><span class="marginnote">直接破产成本常见量级为资产价值的 2%–5%；Bris–Welch–Zhu 2006 用同一批案例对照法庭内外的成本，发现法庭重整并不必然更贵——贵的从来不只是程序费，而是积压、中断与时间。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Chapter 11 是美国制度，不可直接外推：欧洲多走行政重整或强制和解，控制权与谈判结构不同，Djankov 的跨国差异正是这么来的。程序结果受信贷周期影响——DIP 资本收缩时重整变难，清算变多。法官裁量使同一法条产出不同均衡，研究要按地区固定效应分层。本课不展开银行作为债权人的特殊谈判与救助决策，那是后续银行课程的领域；<a href="/econ/financial-distress-restructuring">财务困境与重组</a>与<a href="/econ/bankruptcy-direct-indirect">直接与间接破产成本</a>已分别铺垫困境早期与成本度量，本课不再重复。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>清算与重整的取舍按资产专用性与持续经营价值划界。</li><li>Chapter 11 三构件各对谈判问题：自动止外溢、专属期换时间、DIP 补融资。</li><li>直接成本是小头，债务积压式的事前激励扭曲是大头。</li><li>APR 偏离是谈判均衡：规则是起点，不是终点。</li><li>出处：White 1989；Altman 1984；Myers 1977；Djankov 等 2008；Bris–Welch–Zhu 2006。</li></ul>',5))])}const _=s(c,[["render",p]]);export{P as __pageData,_ as default};
